const txHash = await identityRegistry.write.register(["ipfs://agent"]);
const agentId = await getAgentIdFromRegistration(txHash); // reads the Registered log

const chainId = await publicClient.getChainId();
const block = await publicClient.getBlock();
const deadline = block.timestamp + 240n; // must be at most 5 minutes ahead

const signature = await newWalletSigner.signTypedData({
  account: newWalletSigner.account,
  domain: {
    name: "ERC8004IdentityRegistry",
    version: "1",
    chainId,
    verifyingContract: identityRegistry.address,
  },
  types: {
    AgentWalletSet: [
      { name: "agentId", type: "uint256" },
      { name: "newWallet", type: "address" },
      { name: "owner", type: "address" },
      { name: "deadline", type: "uint256" },
    ],
  },
  primaryType: "AgentWalletSet",
  message: {
    agentId,
    newWallet: newWalletSigner.account.address,
    owner: owner.account.address,
    deadline,
  },
});

await identityRegistry.write.setAgentWallet(
  [agentId, newWalletSigner.account.address, deadline, signature],
  { account: owner.account }
);

await reputationRegistry.write.giveFeedback([
  agentId,
  90, 0,            // value, valueDecimals
  "tag1",
  "tag2",
  "",               // endpoint
  "ipfs://feedback",
  keccak256(toHex("content")),
], { account: client.account });

// feedbackIndex is 1-based; only the original client may revoke
await reputationRegistry.write.revokeFeedback([agentId, 1n], { account: client.account });

import { SDK } from 'agent0-sdk';

const sdk = new SDK({
  chainId: 11155111, // Ethereum Sepolia testnet
  rpcUrl: process.env.RPC_URL,
  privateKey: process.env.PRIVATE_KEY,
  ipfs: 'pinata',
  pinataJwt: process.env.PINATA_JWT,
});

const agent = sdk.createAgent(
  'My AI Agent',
  'An intelligent assistant for various tasks.',
  'https://example.com/agent-image.png'
);
await agent.setMCP('https://mcp.example.com/');
agent.setTrust(true, true, false); // reputation, cryptoEconomic, teeAttestation
agent.setActive(true);

const regTx = await agent.registerIPFS();
const { result: registrationFile } = await regTx.waitConfirmed();

const tx = await sdk.giveFeedback('11155111:123', 85, 'data_analyst', 'finance');
const { receipt } = await tx.waitConfirmed();

function getSummary(
    uint256 agentId,
    address[] calldata clientAddresses, // must be non-empty
    string calldata tag1,
    string calldata tag2
) external view returns (uint64 count, int128 summaryValue, uint8 summaryValueDecimals);
